using MetaheuristicsPlatform.Parameters;
namespace MetaheuristicsPlatform.Algorithms.Constraints.InfeasibilityDrivenEa;
public sealed class InfeasibilityDrivenEaParameters : IMetaheuristicParameters
{ public int PopulationSize { get; init; }=80; public int MaximumGenerations { get; init; }=180; public double DifferentialWeight { get; init; }=0.5; public double CrossoverProbability { get; init; }=0.9; public double InfeasibleFraction { get; init; }=0.2; public void Validate(){if(PopulationSize<4)throw new ArgumentOutOfRangeException(nameof(PopulationSize));if(MaximumGenerations<=0)throw new ArgumentOutOfRangeException(nameof(MaximumGenerations));if(!double.IsFinite(DifferentialWeight)||DifferentialWeight<=0.0)throw new ArgumentOutOfRangeException(nameof(DifferentialWeight));if(!double.IsFinite(CrossoverProbability)||CrossoverProbability<0.0||CrossoverProbability>1.0)throw new ArgumentOutOfRangeException(nameof(CrossoverProbability));if(!double.IsFinite(InfeasibleFraction)||InfeasibleFraction<0.0||InfeasibleFraction>=1.0)throw new ArgumentOutOfRangeException(nameof(InfeasibleFraction));} }
